  filter: {in(k8s.namespace.name, array($Namespace)) and in(partition, array($Partition)) and in(k8s.pod.name, array($Pod))}

23.query:
timeseries append_count_per_sec = avg(zeebe.deferred.append.count.total, rate:1s),
  by: {partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod)) and in(partition, array($Partition))}

25.query:
timeseries control_per_sec = sum(zeebe.flow.control, rate:1s, filter:{outcome == "accepted"}),
  by: {context, partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod)) and in(partition, array($Partition))}

26.query:
timeseries control_per_sec = sum(zeebe.flow.control, rate:1s, filter:{outcome != "accepted"}),
  by: {context, partition, outcome},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod)) and in(partition, array($Partition))}

35.query:
